/*
 * SimpleBME280 Basic — read temp, humidity, pressure
 *
 * Wiring:
 *   VCC -> 5V
 *   GND -> GND
 *   SCL -> A5
 *   SDA -> A4
 *
 * Drag the Temp / Hum / hPa sliders on the sensor
 * to simulate different environmental conditions.
 */

#include <Wire.h>
#include <SimpleBME280.h>

SimpleBME280 bme;

void setup() {
  Serial.begin(115200);
  Wire.begin();
  bme.begin();
  Serial.println("SimpleBME280 ready");
  Serial.println("-------------------");
}

void loop() {
  float tempC   = bme.readTemperature();
  float humPct  = bme.readHumidity();
  float presPa  = bme.readPressure();

  Serial.print("Temp:      ");
  Serial.print(tempC, 1);
  Serial.println(" °C");

  Serial.print("Humidity:  ");
  Serial.print(humPct, 1);
  Serial.println(" %");

  Serial.print("Pressure:  ");
  Serial.print(presPa / 100.0, 1);
  Serial.println(" hPa");

  Serial.println("-------------------");
  delay(2000);
}
